export type ProfileName = keyof typeof PROFILES;

/** Profiles keyed by canonical URL, for resolving `meta.profile`. */
export const PROFILES_BY_URL: ReadonlyMap<string, ProfileEntry> = new Map(
  Object.values(PROFILES).map((entry) => [entry.url, entry]),
);

